/**
 * Standard API response envelope. Identical shape for EVERY status code — 200, 201, 400, 401, 500, etc. Client code always decodes to ApiResponse<T> and checks `success`.
 *
 * success=true  → `data` has the typed payload, `error` is null.
 * success=false → `data` is null, `error` has details.
 */
export type ApiResponse = {
    /**
     * true when the operation succeeded, false on any error.
     */
    success: boolean;
    /**
     * Typed response payload on success. null on failure or no-content actions (logout, delete, etc.). Concrete type is specified per-endpoint via allOf composition.
     */
    data?: unknown;
    /**
     * Error details on failure. Always null on success.
     */
    error?: Error;
    /**
     * Response metadata: request tracing, pagination, timestamps.
     */
    meta?: ResponseMeta;
};

