/**
 * Email Login Request
 * RESTRICTED: Only BUSINESS_BENEFICIARY and SYSTEM_USER can use this flow.
 * Email must be verified before login is allowed.
 * Always produces a SERVER_SIDE session (web portal cookie-based).
 * Flow: 1) Call SendEmailOTP(type=email_login) → 2) Call EmailLogin with
 * otp_id+code
 */
export type EmailLoginRequest = {
    email: string;
    /**
     * From SendEmailOTP
     */
    otp_id: string;
    /**
     * 6-digit OTP code
     */
    code?: string;
    device_id: string;
    /**
     * e.g. "Chrome on Windows"
     */
    device_name?: string;
};

/**
 * Response payload for email login operation. Returns operation results and status.
 */
export type EmailLoginResponse = {
    user_id?: string;
    session_id?: string;
    /**
     * Server-side session fields (web portal)
     * Set as HttpOnly cookie
     */
    session_token?: string;
    /**
     * For CSRF protection
     */
    csrf_token?: string;
    user?: User;
    /**
     * Always SERVER_SIDE
     */
    session_type?: string;
};

/**
 * Event: Email OTP login succeeded (Business Beneficiary / System User)
 */
export type EmailLoginSucceededEvent = {
    event_id?: string;
    user_id?: string;
    session_id?: string;
    /**
     * Masked for audit logs
     */
    email_masked?: string;
    /**
     * BUSINESS_BENEFICIARY or SYSTEM_USER
     */
    user_type?: string;
    timestamp?: string;
    ip_address?: string;
    user_agent?: string;
    device_name?: string;
};

/**
 * Send Email OTP Request
 * Sends OTP to email for: email_verification, email_login, password_reset_email
 * Restricted: only BUSINESS_BENEFICIARY and SYSTEM_USER can use email OTP login
 */
