/**
 * Login Request
 */
export type LoginRequest = {
    /**
     * Accepts 017..., +880..., or 00880... and is normalized to +8801XXXXXXXXX.
     */
    mobile_number?: string;
    /**
     * Optional for B2C OTP-only login. Leave empty only after VerifyOTP succeeds
     * and only for JWT-style mobile/API clients. WEB login still requires password.
     */
    password: string;
    device_id: string;
    /**
     * AUTO-DETECTS: WEB→Server-side, MOBILE→JWT
     */
    device_type?: string;
    /**
     * Human-readable device name
     */
    device_name?: string;
};

/**
 * Response payload for login operation. Returns operation results and status.
 */
export type LoginResponse = {
    user_id?: string;
    session_id?: string;
    /**
     * JWT fields (populated only for mobile/API clients)
     */
    access_token?: string;
    refresh_token?: string;
    access_token_expires_in?: number;
    refresh_token_expires_in?: number;
    /**
     * Server-side session fields (populated only for web clients)
     * Note: For web, session_id is also set in HTTP-Only cookie
     * Not sent to client, just for logging
     */
    session_token?: string;
    /**
     * For web CSRF protection
     */
    csrf_token?: string;
    user?: User;
    /**
     * SERVER_SIDE or JWT
     */
    session_type?: string;
    /**
     * MFA fields — set when mfa_required=true; client must call VerifyTOTP before getting tokens
     */
    mfa_required?: boolean;
    /**
     * "TOTP", "SMS", "EMAIL"
     */
    mfa_method?: string;
    /**
     * mfa_session_token: opaque 5-min token; pass back in VerifyTOTPRequest to get real session tokens.
     */
    mfa_session_token?: string;
    password_change_required?: boolean;
};

/**
 * Logout Request
 * Note: For web clients, session_id is extracted from HTTP-Only cookie
 * For mobile clients, provide access_token to identify session
 */
export type LogoutRequest = {
    /**
     * Optional: extracted from cookie for web
     */
    session_id: string;
    /**
     * Optional: for JWT logout (mobile/API)
     */
    access_token?: string;
    /**
     * Optional: user_initiated, security, etc.
     */
    logout_reason?: string;
};

/**
 * Response payload for logout operation. Returns operation results and status.
 */
export type LogoutResponse = {
    /**
     * Indicates if session was successfully revoked
     */
    session_revoked?: boolean;
};

